+
+/** Keep the schemes (Settings' Save): in use at once here, and in Studio's prefs for every window and next time. */
+export async function saveKeyPrefs(next: KeyPrefs): Promise<void> {
+  set(next);
+  await api.setPrefs({ keys: next });
